public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    // Check if start and end are within bounds
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
        end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // If start equals end, we can trivially travel
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency list
    // Each node is represented by a pair (row, col)
    // We'll use a map from node to list of neighbors
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length < 4) {
                continue;
            }
            int r1 = path[0], c1 = path[1], r2 = path[2], c2 = path[3];

            // Validate coordinates
            if (r1 < 0 || r1 >= n || c1 < 0 || c1 >= n || r2 < 0 || r2 >= n || c2 < 0 || c2 >= n) {
                continue;
            }

            String node1 = r1 + "," + c1;
            String node2 = r2 + "," + c2;

            graph.computeIfAbsent(node1, k -> new java.util.ArrayList<>()).add(node2);
            graph.computeIfAbsent(node2, k -> new java.util.ArrayList<>()).add(node1);
        }
    }

    // BFS from start to end
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.LinkedList<>();

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();

        if (current.equals(endKey)) {
            return "can be travelled";
        }

        java.util.List<String> neighbors = graph.get(current);
        if (neighbors != null) {
            for (String neighbor : neighbors) {
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.offer(neighbor);
                }
            }
        }
    }

    return "cannot be travelled";
}
