public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the squared distances between each pair of points
    long d12 = (long)(x1 - x2) * (x1 - x2) + (long)(y1 - y2) * (y1 - y2);
    long d23 = (long)(x2 - x3) * (x2 - x3) + (long)(y2 - y3) * (y2 - y3);
    long d13 = (long)(x1 - x3) * (x1 - x3) + (long)(y1 - y3) * (y1 - y3);

    // Check if any two points are the same (distance is 0)
    if (d12 == 0 || d23 == 0 || d13 == 0) {
        return false;
    }

    // Check if the three points are collinear using the cross product
    // If the cross product is 0, the points are collinear
    long cross = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);

    return cross != 0;
}
