public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // dp[i] represents the minimum number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: i ones
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }

    return dp[n];
}
